/**
 * The numbered questions inside each section of the Dalhousie application form
 * for prospective research, and where each of the tool's own questions prints.
 *
 * Read from `application-human-ethics-prospective-research.docx` (version 2025)
 * on 2026-10-31. Two numbers are generated by Word's list numbering and do not
 * appear in the document text, so they were read through Word itself: 2.7.2
 * (retention and destruction) and 2.8.2 (keeper of the data). Every other number
 * is typed into the form.
 *
 * Why this file exists. KJ's feedback of 22 October 2026 was that the Word
 * download groups answers by section while the form asks numbered questions, so
 * every answer is copied across by hand and sorted on the way. Printing each
 * answer under the form's own question number makes that copy one to one.
 *
 * Section 1 is not here. It holds names, Banner numbers and phone numbers, which
 * the tool is built never to ask for, so the document prints it as labelled
 * blanks.
 */

export interface FormQuestion {
  /** The form's own number. Sections with a single question use the section number. */
  number: string
  /** The section it sits in, matching `FORM_SECTIONS`. */
  section: string
  /** A short label for the document. The form's full wording stays on the form. */
  label: string
}

