const QUESTIONS_BY_NUMBER: Record<string, FormQuestion> = Object.fromEntries(
  FORM_QUESTIONS.map((question) => [question.number, question]),
)

export function formQuestionsFor(section: string): FormQuestion[] {
  return FORM_QUESTIONS.filter((question) => question.section === section)
}

const TOOL_COVERED = new Set(Object.values(QUESTION_TO_FORM).flatMap((numbers) => numbers ?? []))

/** The form questions in a section that at least one of the tool's questions feeds. */
export function toolCoveredNumbers(section: string): string[] {
  return formQuestionsFor(section)
    .map((question) => question.number)
    .filter((number) => TOOL_COVERED.has(number))
}

/** The form question numbers a tool question prints under. Empty when it prints nowhere. */
export function formNumbersFor(questionKey: string): string[] {
  return QUESTION_TO_FORM[questionKey] ?? []
}

/**
 * The section a tool question belongs to for drafting and printing.
 *
 * This is the section of the form question it prints under, which differs from
 * the intake section for two questions: dependence (asked at 2.3, printed at 2.5.1)
 * and incentives (asked at 2.4, printed at 2.6.5). Questions with no form field
 * keep the section they were asked in.
 */
export function printSectionFor(questionKey: string, askedIn: string | undefined): string | undefined {
  const first = formNumbersFor(questionKey)[0]
  return first ? (QUESTIONS_BY_NUMBER[first]?.section ?? askedIn) : askedIn
}
